def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []

    # Find connected components that form complete rectangular outlines.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == color
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            perimeter = (
                {(r0, x) for x in range(c0, c1 + 1)}
                | {(r1, x) for x in range(c0, c1 + 1)}
                | {(y, c0) for y in range(r0, r1 + 1)}
                | {(y, c1) for y in range(r0, r1 + 1)}
            )
            if perimeter <= cells:
                frames.append({
                    "color": color, "r0": r0, "r1": r1,
                    "c0": c0, "c1": c1,
                    "size": (r1 - r0 + 1, c1 - c0 + 1),
                })

    if not frames:
        return [row[:] for row in grid]

    counts = {}
    for f in frames:
        counts[f["size"]] = counts.get(f["size"], 0) + 1
    target_size = max(counts, key=counts.get)
    group = [f for f in frames if f["size"] == target_size]

    def interior_pattern(frame):
        return {
            (r - frame["r0"], c - frame["c0"])
            for r in range(frame["r0"] + 1, frame["r1"])
            for c in range(frame["c0"] + 1, frame["c1"])
            if grid[r][c] == frame["color"]
        }

    donor = max(group, key=lambda f: len(interior_pattern(f)))
    pattern = interior_pattern(donor)

    out = [[0] * w for _ in range(h)]
    for frame in group:
        r0, r1 = frame["r0"], frame["r1"]
        c0, c1 = frame["c0"], frame["c1"]
        color = frame["color"]

        for c in range(c0, c1 + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = color
            out[r][c1] = color

        for dr, dc in pattern:
            rr, cc = r0 + dr, c0 + dc
            if r0 < rr < r1 and c0 < cc < c1:
                out[rr][cc] = color

    return out
